    def validate(self) -> Dict[str, str]:
        """Validate all config files against monotonicity and schema rules."""
        results = validate_all_policies()

        # Schema coverage of registry HARD constraints (existing checks)
        schema_hard_bools = {
            dp for dp, defn in self._schema.items()
            if defn.constraint_class == "HARD" and defn.type == "bool"
        }
        registry_hard_bools = set(HARD_CONSTRAINTS.keys())
        missing = registry_hard_bools - schema_hard_bools
        if missing:
            results["schema_coverage/hard_bools"] = (
                f"Schema missing HARD bool constraints: {sorted(missing)}"
            )

        schema_hard_thresholds = {
            dp for dp, defn in self._schema.items()
            if defn.constraint_class == "HARD" and defn.type in ("int", "float")
        }
        registry_hard_thresholds = set(HARD_THRESHOLDS.keys())
        missing_thresh = registry_hard_thresholds - schema_hard_thresholds
        if missing_thresh:
            results["schema_coverage/hard_thresholds"] = (
                f"Schema missing HARD threshold constraints: {sorted(missing_thresh)}"
            )

        schema_hard_strings = {
            dp for dp, defn in self._schema.items()
            if defn.constraint_class == "HARD" and defn.type == "string"
        }
        registry_hard_strings = set(HARD_STRINGS.keys())
        missing_str = registry_hard_strings - schema_hard_strings
        if missing_str:
            results["schema_coverage/hard_strings"] = (
                f"Schema missing HARD string constraints: {sorted(missing_str)}"
            )

        # New: validate each config file against schema constraints
        layer_order = {"universal": 0, "domain": 1, "task": 2, "model": 3}
        universal_vals = {}
        if (REGISTRY_DIR / "universal.toml").exists():
            universal = _load_toml(REGISTRY_DIR / "universal.toml")
            universal_vals = _flatten_dict(universal)

        def validate_file(path: Path, layer: str) -> None:
            try:
                config = _load_toml(path)
            except Exception as e:
                results[f"{layer}/{path.stem}"] = f"Failed to load TOML: {e}"
                return
            flat = _flatten_dict(config)
            for dp, val in flat.items():
                defn = self._schema.get(dp)
                if not defn:
                    continue  # unknown parameter – schema coverage already warned
                # Type check
                if defn.type == "bool" and not isinstance(val, bool):
                    results.setdefault(f"{layer}/{path.stem}", []).append(
                        f"{dp}: expected bool, got {type(val).__name__}"
                    )
                elif defn.type == "int" and not isinstance(val, int):
                    results.setdefault(f"{layer}/{path.stem}", []).append(
                        f"{dp}: expected int, got {type(val).__name__}"
                    )
                elif defn.type == "float" and not isinstance(val, (int, float)):
                    results.setdefault(f"{layer}/{path.stem}", []).append(
                        f"{dp}: expected float, got {type(val).__name__}"
                    )
                elif defn.type in ("string", "enum") and not isinstance(val, str):
                    results.setdefault(f"{layer}/{path.stem}", []).append(
                        f"{dp}: expected string, got {type(val).__name__}"
                    )
                # Allowed values
                if defn.allowed_values and val not in defn.allowed_values:
                    results.setdefault(f"{layer}/{path.stem}", []).append(
                        f"{dp}: value {val!r} not in {defn.allowed_values}"
                    )
                # Min‑layer enforcement
                if layer_order[layer.split('/')[0]] < layer_order[defn.min_layer]:
                    results.setdefault(f"{layer}/{path.stem}", []).append(
                        f"{dp}: defined in layer {layer} but min_layer is {defn.min_layer}"
                    )
                # HARD‑constraint monotonicity (universal → lower layers)
                if defn.constraint_class == "HARD" and layer != "universal":
                    universal_val = universal_vals.get(dp, defn.default)
                    if val != universal_val:
                        results.setdefault(f"{layer}/{path.stem}", []).append(
                            f"{dp}: HARD constraint changed from {universal_val!r} to {val!r}"
                        )

        # Scan all configs
        for toml_path in (REGISTRY_DIR / "domains").glob("*.toml"):
            validate_file(toml_path, "domain")
        for toml_path in (REGISTRY_DIR / "tasks").glob("*.toml"):
            validate_file(toml_path, "task")
        for toml_path in (REGISTRY_DIR / "models").glob("*.toml"):
            validate_file(toml_path, "model")

        # Convert any accumulated lists to strings
        for key in list(results.keys()):
            if isinstance(results[key], list):
                results[key] = "; ".join(results[key])

        return results
